#!/usr/bin/env python3
"""
Prontera Grind - finished update, self-installing.

    python3 UPDATE-BOOTSTRAP.py

Puts the finished index.html and tools/ into this repo, recovers the sprite
sheets from git if they are missing, rebuilds assets/sprite_pack_data.js from
Sprite/*.png, and runs the three test suites.

Safe to run twice.  Needs python3, node, and network once for pip.
"""
import base64
import lzma
import io
import os
import shutil
import subprocess
import sys
import tarfile
import tempfile

BLOB = """"""

# sha256 of the finished index.html - the patch is verified against this
V7_SHA = "b6ec63eafea3d57c08c068b5086003faeb46053fcb57838c2281bc2312e27084"
VENV = '/tmp/venv'
BAD = 0


def sh(cmd, quiet=False):
    if not quiet:
        print('    $ ' + (cmd if isinstance(cmd, str) else ' '.join(cmd)), flush=True)
    kw = dict(shell=isinstance(cmd, str))
    if quiet:
        kw['stdout'] = subprocess.DEVNULL
        kw['stderr'] = subprocess.DEVNULL
    return subprocess.run(cmd, **kw).returncode


def note(msg):
    print('    ' + msg, flush=True)


def sha(path):
    import hashlib
    return hashlib.sha256(open(path, 'rb').read()).hexdigest()


def main():
    global BAD
    repo = os.path.dirname(os.path.abspath(__file__))
    os.chdir(repo)
    print('Prontera Grind update bootstrap')
    print('  repo: %s' % repo)

    # ------------------------------------------------------------- 1: unpack
    print('[1/6] unpacking')
    raw = lzma.decompress(base64.b64decode(''.join(BLOB.split())))
    tmp = tempfile.mkdtemp(prefix='prg-boot-')
    with tarfile.open(fileobj=io.BytesIO(raw), mode='r:gz') as t:
        try:
            t.extractall(tmp, filter='data')
        except TypeError:
            t.extractall(tmp)

    # finished files over the top of the repo
    src = os.path.join(tmp, 'files')
    for base, _, names in os.walk(src):
        rel = os.path.relpath(base, src)
        dst = repo if rel == '.' else os.path.join(repo, rel)
        os.makedirs(dst, exist_ok=True)
        for n in names:
            shutil.copy2(os.path.join(base, n), os.path.join(dst, n))
    note('wrote index-independent files: tools/, READ-ME-FIRST.md')

    # ------------------------------------------------------- 2: index.html
    print('[2/6] index.html')
    patches = sorted(os.listdir(os.path.join(tmp, 'patches')))
    ok = False
    for p in patches:
        if sh(['git', 'apply', '--whitespace=nowarn', os.path.join(tmp, 'patches', p)], quiet=True) == 0:
            if sha('index.html') == V7_SHA:
                note('applied %s - index.html is the finished v7 build' % p)
                ok = True
                break
            sh(['git', 'checkout', '--', 'index.html'], quiet=True)
    if not ok:
        note('patches did not apply to the index.html in the working tree;')
        note('restoring the copy from commit b2bed6b first, then patching')
        sh('git show b2bed6b:index.html > /tmp/prg_base_index.html 2>/dev/null || true', quiet=True)
        if os.path.exists('/tmp/prg_base_index.html') and os.path.getsize('/tmp/prg_base_index.html') > 1000:
            shutil.copy2('/tmp/prg_base_index.html', 'index.html')
            for p in patches:
                if sh(['git', 'apply', '--whitespace=nowarn', os.path.join(tmp, 'patches', p)], quiet=True) == 0:
                    if sha('index.html') == V7_SHA:
                        note('applied %s' % p)
                        ok = True
                        break
                shutil.copy2('/tmp/prg_base_index.html', 'index.html')
    if ok:
        game = open('index.html').read()
        note("BUILD = '2026-10-03 sprites-v7 all 19 classes' (%d bytes)" % len(game))
    else:
        print('  !! COULD NOT BUILD index.html - stop here and report this')
        print('     expected sha256 %s' % V7_SHA)
        BAD += 1
        game = open('index.html').read()

    # ---------------------------------------------------------- 3: sheets
    print('[3/6] sprite sheets')
    want = 21
    have = len([f for f in os.listdir('Sprite') if f.lower().endswith('.png')]) if os.path.isdir('Sprite') else 0
    if have < want:
        for ref in ('origin/main', 'origin/HEAD', 'b2bed6b'):
            if sh(['git', 'checkout', ref, '--', 'Sprite/'], quiet=True) == 0:
                have = len([f for f in os.listdir('Sprite') if f.lower().endswith('.png')])
                if have >= want:
                    note('recovered %d sheets from %s' % (have, ref))
                    break
    note('sheets in Sprite/: %d' % have)
    if have < want:
        note('!! expected %d - the pack rebuild will come out short' % want)
        BAD += 1

    # missing inputs the pack tool reads (present on main, not on every branch)
    for dep in ('assets/thief_sprites_data.js',):
        if not os.path.exists(dep):
            for ref in ('origin/main', 'origin/HEAD', 'b2bed6b'):
                if sh(['git', 'checkout', ref, '--', dep], quiet=True) == 0 and os.path.exists(dep):
                    note('recovered %s from %s' % (dep, ref))
                    break
            if not os.path.exists(dep):
                note('!! %s is missing - the pack tool needs it' % dep)
                BAD += 1

    # ----------------------------------------------------------- 4: tools
    print('[4/6] python tools for the pack rebuild')
    py = os.path.join(VENV, 'bin', 'python')
    if not os.path.exists(py):
        note('making a venv in %s' % VENV)
        sh([sys.executable, '-m', 'venv', VENV])
    if sh([py, '-c', 'import PIL, numpy, scipy'], quiet=True) != 0:
        note('installing pillow, numpy, scipy')
        sh([py, '-m', 'pip', '-q', 'install', 'pillow', 'numpy', 'scipy'])
    if sh([py, '-c', 'import PIL, numpy, scipy'], quiet=True) != 0:
        print('  !! pillow / numpy / scipy could not be installed'); BAD += 1

    # ------------------------------------------------------------ 5: pack
    print('[5/6] rebuilding assets/sprite_pack_data.js from Sprite/')
    if sh([py, 'tools/make_sprite_pack.py']) != 0:
        print('  !! the pack build failed'); BAD += 1
    else:
        note('assets/sprite_pack_data.js: %.1f MB' % (os.path.getsize('assets/sprite_pack_data.js') / 1048576.0))
        if sh(['node', '-e',
               "global.window={};require('./assets/sprite_pack_data.js');"
               "const b=Object.keys(window.SPRITE_PACK.bodies);"
               "console.log('    bodies ('+b.length+'): '+b.join(' '));"
               "if(b.length!==19)process.exit(1)"]) != 0:
            print('  !! expected 19 bodies'); BAD += 1

    import re
    inline = '\n;\n'.join(re.findall(r'<script(?![^>]*\bsrc=)[^>]*>(.*?)</script>', game, re.S))
    open('/tmp/game_inline.js', 'w').write(inline)
    i, j = game.find('const PACK_BODY='), game.find('function ensureHero(')
    if i > 0 and j > i:
        open('/tmp/pack_block.js', 'w').write(game[i:j])

    # ----------------------------------------------------------- 6: tests
    print('[6/6] test suites')
    if sh(['node', '--check', '/tmp/game_inline.js'], quiet=True) != 0:
        print('  !! index.html inline JS has a syntax error'); BAD += 1
    else:
        note('index.html inline JS parses OK')
    for t, tail in (('pack_sim.js', 1), ('class_change_sim.js', 2), ('save_load_sim.js', 2)):
        p = subprocess.run(['node', 'tools/tests/' + t], capture_output=True, text=True)
        out = [l for l in p.stdout.strip().splitlines() if l.strip()]
        print('    --- %s ---' % t)
        for l in (out[-tail:] if out else ['(no output)']):
            print('    ' + l)
        if p.returncode != 0:
            BAD += 1

    shutil.rmtree(tmp, ignore_errors=True)
    print()
    if BAD:
        print('FINISHED WITH %d PROBLEM(S) - see the !! lines above' % BAD)
    else:
        print('DONE - the update is built and all three test suites pass.')
    print("""
Finish from here:

    git rm -f UPDATE-BOOTSTRAP.py        # one-shot helper, already run
    git add -A
    git commit -m "All 19 classes on their own sprite art + class change is a restart"
    git push -u origin HEAD
    gh pr create --base main --fill

then give the user the pull-request link.  The game itself only needs the two
files index.html and assets/sprite_pack_data.js; the rest is tools and notes.
""")
    return 0 if BAD == 0 else 1


if __name__ == '__main__':
    sys.exit(main())
